const FALLBACK={head:{x:50,y:9,w:57},eyes:{x:50,y:31,w:42},ears:{x:50,y:37,w:55},neck:{x:50,y:65,w:44},chest:{x:50,y:82,w:88},waist:{x:50,y:91,w:78},feet:{x:50,y:98,w:62},back:{x:50,y:73,w:75}};
const profile=(avatar)=>AVATAR_FIT_PROFILES[String(avatar||'john').toLowerCase()]||AVATAR_FIT_PROFILES.john;
const anchor=(avatar,key)=>({...FALLBACK[key],...(profile(avatar)?.[key]||{})});
const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
function itemTuning(item,fit){
 if(!item||!item.fit||typeof item.fit!=='object') return fit;
 const out={...fit};
 if(Number.isFinite(item.fit.x)) out.x=clamp(out.x+(item.fit.x-50)*0.12,0,100);
 if(Number.isFinite(item.fit.y)) out.y=clamp(out.y+item.fit.y*0.10,0,100);
 if(Number.isFinite(item.fit.w)) out.w=clamp((out.w*0.65)+(item.fit.w*0.35),8,120);
 if(Number.isFinite(item.fit.h)) out.h=clamp(item.fit.h,8,100);
 if(Number.isFinite(item.fit.r)) out.r=item.fit.r;
 return out;
}
function baseFit(avatar,slot,item){
 const p=profile(avatar), dog=!!p.dog;
 let f;
 if(slot==='hat'||slot==='hair'){const a=anchor(avatar,'head');f={x:a.x,y:a.y+(slot==='hair'?2:-1),w:a.w*(slot==='hair'?1.12:1.08)}}
 else if(slot==='glasses'||slot==='face'){const a=anchor(avatar,'eyes');f={x:a.x,y:a.y+(slot==='face'?2:0),w:a.w*(slot==='glasses'?1.08:1.10)}}
 else if(slot==='headset'){const a=anchor(avatar,'ears');f={x:a.x,y:a.y-7,w:a.w*1.22}}
 else if(slot==='filter'){const a=anchor(avatar,'head');f={x:a.x,y:a.y+30,w:a.w*1.34}}
 else if(slot==='earrings'){const a=anchor(avatar,'ears');f={x:a.x,y:a.y+15,w:a.w*1.18}}
 else if(slot==='neck'){const a=anchor(avatar,'neck');f={x:a.x,y:a.y+5,w:a.w*1.22}}
 else if(slot==='top'){const a=anchor(avatar,'chest');f={x:a.x,y:a.y,w:a.w,h:dog?31:38}}
 else if(slot==='outerwear'){const a=anchor(avatar,'chest');f={x:a.x,y:a.y+1,w:a.w*1.06,h:dog?34:42}}
 else if(slot==='onepiece'||slot==='costume'){const a=anchor(avatar,'chest');f={x:a.x,y:a.y+2,w:a.w*1.08,h:dog?40:54}}
 else if(slot==='bottom'){const a=anchor(avatar,'waist');f={x:a.x,y:a.y+3,w:a.w,h:dog?16:22}}
 else if(slot==='shoes'){const a=anchor(avatar,'feet');f={x:a.x,y:a.y+1,w:a.w,h:15}}
 else if(slot==='wrists'){const a=anchor(avatar,'chest');f={x:a.x,y:a.y+1,w:a.w*.92,h:18}}
 else if(slot==='back'){const a=anchor(avatar,'back');f={x:a.x,y:a.y,w:a.w*1.1,h:dog?38:48}}
 else if(slot==='attachment'){const a=anchor(avatar,'back');f={x:a.x,y:a.y-18,w:a.w*1.18,h:dog?52:72}}
 else if(slot==='badge'){const a=anchor(avatar,'chest');f={x:a.x+a.w*.28,y:a.y-7,w:dog?16:17}}
 else f={x:50,y:50,w:35};
 if(dog){
   if(slot==='hat') f={...f,y:f.y+3,w:f.w*.95};
   if(slot==='glasses'||slot==='face') f={...f,y:f.y+1,w:f.w*.96};
   if(slot==='earrings') f={...f,y:f.y-3,w:f.w*.92};
   if(slot==='neck') f={...f,y:f.y+1,w:f.w*1.12};
 }
 return itemTuning(item,{...f,r:0,hidden:false});
}
export function fitProfileForAvatar(avatar='john',slot='hat',item=null,variant=0){return baseFit(avatar,slot,item)}
export function normalizeEquipped(raw={}){const out=Object.fromEntries(COSMETIC_SLOTS.map(s=>[s,null]));if(!raw||typeof raw!=='object')return out;for(const [oldSlot,id0] of Object.entries(raw)){const id=String(id0||'');const item=COSMETIC_BY_ID[id];if(item)out[item.slot]=id}return out}
export function cosmeticOverlayHTML(equipped={},avatar='john',variant=0){const eq=normalizeEquipped(equipped);return COSMETIC_SLOTS.map(slot=>{const item=COSMETIC_BY_ID[eq[slot]];if(!item)return'';const f=fitProfileForAvatar(avatar,slot,item,variant);return `<img class="avatar-cosmetic avatar-cosmetic-${slot} ${item.animated?'animated-cosmetic':''}" data-cosmetic-id="${item.id}" src="${item.asset}" alt="" aria-hidden="true" style="--cx:${f.x}%;--cy:${f.y}%;--cw:${f.w}%;--ch:${Number.isFinite(f.h)?`${f.h}%`:'auto'};--cr:${f.r||0}deg">`}).join('')}
export function cosmeticLabelList(equipped={}){const eq=normalizeEquipped(equipped);return COSMETIC_SLOTS.map(slot=>COSMETIC_BY_ID[eq[slot]]?.name).filter(Boolean)}
export function cosmeticCategories(){return ['All',...new Set(COSMETIC_CATALOG.map(x=>x.category))]}
export function avatarFitProfile(avatar='john'){return JSON.parse(JSON.stringify(profile(avatar)))}
